    88	export function StepsTab({ run }: { run: Run }) {
    89	  const [params, setParams] = useSearchParams();
    90	  const [details, setDetails] = useState(false);
    91	  const [exceptionId, setExceptionId] = useState<string | null>(null);
    92	  const manual = useRef(!!params.get('step'));
    93	  const running = run.steps.find(step => step.status === 'running');
    94	  const fallback = running || run.steps.find(step => step.status === 'awaiting_approval' || step.status === 'failed') || [...run.steps].reverse().find(step => step.status !== 'pending' && step.kind === 'calc') || run.steps[0];
    95	  const selectedId = params.get('step') || fallback?.id;
    96	  const step = run.steps.find(item => item.id === selectedId) || fallback;
    97	  const ref = params.get('ref');
    98	
    99	  useRunEvents(run.id, event => {
   100	    // Follow the agent while the user has not picked a step.
   101	    if (event.type === 'step_started' && !manual.current) setParams(current => { current.set('step', event.step_id); current.delete('ref'); current.delete('dataset'); return current; }, { replace: true });
   102	  });
   103	  useEffect(() => { setExceptionId(null); }, [step?.id]);
   104	  const select = (id: string) => {
   105	    manual.current = true;
   106	    setParams(current => { const next = new URLSearchParams({ step: id }); const volume = current.get('volume'); if (volume) next.set('volume', volume); return next; }, { replace: true });
   107	  };
   108	  const { data: exceptions } = useExceptions(run.id, !!exceptionId);
   109	  const exception = exceptions?.find(item => item.id === exceptionId);
   110	  const filters = useMemo(() => (ref ? [{ column: 'id', op: 'eq' as const, value: ref }] : undefined), [ref]);
   111	
   112	  if (!step) return <Empty title="Este run não tem passos" />;
   113	  return (
   114	    <div className="wb">
   115	      <aside className="wb-side">
   116	        <div className="card wb-steps">
   117	          <div className="run-col-head"><span>Passos</span><span className="muted num">{run.steps.length}</span></div>
   118	          <StepList steps={run.steps} selected={step.id} onSelect={select} onDetails={id => { select(id); setDetails(true); }} />
   119	        </div>
   120	        <RunSummaryCard run={run} />
   121	      </aside>
   122	      <section className="card wb-card">
   123	        {step.kind === 'gate' ? <GateView run={run} step={step} />
   124	          : <StepWorkspace run={run} step={step} initialFilters={filters} onException={setExceptionId} onDetails={() => setDetails(true)} chat={(table, synthetic) => <ChatDock run={run} step={step} table={table} synthetic={synthetic} />} />}
   125	      </section>
   126	      {exception ? (
   127	        <Sheet eyebrow="Exceção" title={readable(exception.kind)} sub={`${exception.merchant} · ${exception.ref_origem}`} onClose={() => setExceptionId(null)}
   128	          footer={run.status === 'awaiting_approval' && !run.draft
   129	            ? <Link className="btn primary" to={`/runs/${run.id}/revisao?passo=${exception.step_type}`}><Icon name="arrowRight" />Decidir na revisão</Link> : undefined}>
   130	          {/* The data desk is read-only: decisions happen in the Revisão tab. */}
   131	          <ExceptionDetail exception={exception} run={run} editable={false} />
   132	        </Sheet>
   133	      ) : details ? (
   134	        <Sheet eyebrow="Detalhes do passo" title={step.title} onClose={() => setDetails(false)}>
   135	          <StepDetail run={run} step={step} onException={id => { setDetails(false); setExceptionId(id); }} />
   136	        </Sheet>
   137	      ) : null}
   138	    </div>
   139	  );
   140	}
